CAT = "cpatcpPartnership"; SEG = "PTR"
Q = [
("Gil contributes property with a basis of $30,000 and a value of $90,000, subject to a $60,000 recourse mortgage the partnership assumes, for a one-third interest. The three general partners share losses equally. Gil recognizes gain of:",
 "$10,000", ["$30,000", "$0", "$40,000"],
 "He keeps a $20,000 share of the debt, so net relief is $40,000, treated as a cash distribution. It exceeds his $30,000 basis by $10,000 (section 731).", 10000),
("A general partnership with two partners who share losses equally borrows $80,000 on recourse terms. Each partner's outside basis:",
 "Rises by $40,000", ["Rises by $80,000", "Does not change", "Rises by $20,000"],
 "An increase in a partner's share of partnership liabilities is treated as a cash contribution (section 752(a)), and recourse debt follows the equal economic risk of loss."),
("A 30% partner lends $50,000 to the partnership on a recourse note. For basis purposes the loan is allocated:",
 "All to the lending partner", ["30% to the lending partner", "By profit-sharing ratios", "To no partner at all"],
 "The lending partner bears the economic risk of loss on her own loan, so the whole liability is allocated to her (Reg. 1.752-2(c))."),
("Partnership nonrecourse debt that is not tied to minimum gain or built-in gain is generally shared:",
 "In profit-sharing ratios", ["In loss-sharing ratios", "Equally per partner", "Only by general partners"],
 "Excess nonrecourse liabilities are allocated by the partners' shares of profits (Reg. 1.752-3(a)(3)), since no partner bears the risk of loss."),
("Eli's outside basis is $25,000. In a current distribution the partnership gives him $10,000 of cash and a parcel of land with a partnership basis of $20,000 and a value of $28,000. Eli's basis in the parcel is:",
 "$15,000", ["$20,000", "$28,000", "$25,000"],
 "Cash is applied first and cuts outside basis to $15,000. The parcel takes the partnership's $20,000 basis, limited to the $15,000 left (section 732(a)(2)).", 15000),
("A partner with an outside basis of $50,000 receives $10,000 of cash and inventory with a partnership basis of $15,000 in complete liquidation of her interest. She recognizes:",
 "A $25,000 capital loss", ["No loss; inventory basis $40,000", "A $25,000 ordinary loss", "No loss; inventory basis $15,000"],
 "When only cash, unrealized receivables and inventory are received, a loss is recognized for basis left over (section 731(a)(2)): $50,000 - $10,000 - $15,000 = $25,000.", 25000),
("A partner with an outside basis of $50,000 receives, in complete liquidation, $10,000 of cash, inventory with a partnership basis of $15,000 and land with a partnership basis of $5,000. Her basis in the land is:",
 "$25,000", ["$5,000", "$35,000", "$40,000"],
 "No loss is allowed because she received land. Cash and inventory reduce basis to $25,000, all of which goes to the land (section 732(b)).", 25000),
("A partnership with ordinary income of $100,000 before guaranteed payments pays partner A, a 40% partner, a $30,000 guaranteed payment. A's total ordinary income from the partnership is:",
 "$58,000", ["$70,000", "$40,000", "$28,000"],
 "The guaranteed payment is deducted by the partnership, leaving $70,000. A reports the $30,000 payment plus 40% x $70,000 = $28,000, a total of $58,000.", 58000),
("A partner owning 60% of a partnership sells land to the partnership at a $9,000 loss. The loss is:",
 "Not deductible by the partner", ["Deductible as a capital loss", "Deductible as an ordinary loss", "Deferred until year end"],
 "Section 707(b)(1) disallows losses on sales between a partnership and a partner owning more than 50%. The partnership can use it to offset a later gain."),
("A buyer pays $90,000 for a one-third interest when the partnership's inside basis is $150,000, so his share of inside basis is $50,000. With a section 754 election in effect, the section 743(b) adjustment is:",
 "$40,000", ["$90,000", "$0", "$13,333"],
 "The adjustment is the buyer's outside basis less his share of inside basis: $90,000 - $50,000 = $40,000, made to partnership property for him alone.", 40000),
("Even with no section 754 election, a basis adjustment is required on a transfer when the partnership has a substantial built-in loss, meaning inside basis exceeds asset value by more than:",
 "$250,000", ["$750,000", "$500,000", "$1,000,000"],
 "Section 743(d) defines a substantial built-in loss by the $250,000 test, or a loss of more than $250,000 allocated to the transferee on a hypothetical sale."),
("Which tax election is made by the partnership itself rather than by each partner?",
 "Its depreciation method", ["Credit or deduction for foreign tax", "Reducing basis for canceled debt", "Deducting mining exploration costs"],
 "Section 703(b) makes elections at the partnership level except for a few, including the foreign tax credit, the canceled debt basis reduction and mining exploration costs."),
("If no group of majority partners shares a tax year and the principal partners do not share one either, a partnership must use:",
 "The year of least deferral", ["The calendar year", "Any year it chooses", "Its largest partner's year"],
 "Section 706(b)(1)(B) applies the majority interest year first, then the principal partners' year, and then the year that gives the least aggregate deferral of income."),
("A calendar-year partnership earns $120,000 evenly over the year. A 25% partner sells her whole interest on March 31, and the partnership prorates by month. Income allocated to her is:",
 "$7,500", ["$30,000", "$22,500", "$15,000"],
 "Under the proration method her share covers 3 of 12 months: $120,000 x 25% x 3/12 = $7,500.", 7500),
("A calendar-year partnership earned $50,000 from January through March and $70,000 for the rest of the year. A 25% partner sells her whole interest on March 31, and the interim closing method is used. Income allocated to her is:",
 "$12,500", ["$7,500", "$30,000", "$17,500"],
 "With an interim closing, she is allocated her share of income actually earned while she was a partner: 25% x $50,000 = $12,500.", 12500),
("A partner contributes land with a basis of $20,000 and a value of $50,000 to a 50/50 partnership, which later sells it for $56,000. The gain allocated to the contributing partner is:",
 "$33,000", ["$18,000", "$36,000", "$30,000"],
 "Section 704(c) allocates the $30,000 built-in gain to the contributor, and the $6,000 of later gain is split equally: $30,000 + $3,000 = $33,000.", 33000),
("A partner contributes property with built-in gain, and the partnership distributes it to another partner. The contributor recognizes the remaining precontribution gain if this happens within:",
 "7 years of the contribution", ["2 years of the contribution", "5 years of the contribution", "3 years of the contribution"],
 "Section 704(c)(1)(B) treats the contributor as selling the property if it is distributed to another partner within 7 years of its contribution."),
("A partner contributes property and receives a cash distribution from the partnership 14 months later. Under the regulations, the two transfers are presumed to be:",
 "A sale of the property", ["A tax-free distribution", "A loan to the partner", "A guaranteed payment"],
 "Transfers within two years of each other are presumed to be a disguised sale under Reg. 1.707-3(c) unless the facts clearly show otherwise."),
("A partner contributes inventory to a partnership, and the partnership sells it within 5 years at a gain. The gain is:",
 "Ordinary income", ["Capital gain", "Section 1231 gain", "Tax-free to the partners"],
 "Section 724(b) keeps the ordinary character of contributed inventory for 5 years, even if the partnership would hold it as a capital asset."),
("A partner's basis on January 1 is $40,000. Her shares: ordinary loss $15,000, tax-exempt income $3,000 and nondeductible expenses $1,000. She receives $5,000 of cash, and her share of liabilities rises by $8,000. Her basis at year end is:",
 "$30,000", ["$45,000", "$31,000", "$38,000"],
 "Increases come first ($40,000 + $3,000 + $8,000 = $51,000), then the distribution ($46,000), then nondeductible expenses ($45,000), then the loss: $30,000.", 30000),
]
